INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Any object thrown or launched into the air acted on mainly by gravity is a projectile.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'The curved path a projectile follows is called its trajectory.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Projectile motion combines constant horizontal motion and accelerated vertical motion.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'On level ground, a launch angle near 45° gives the maximum horizontal range.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Complementary angles like 30° and 60° give almost the same range.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Higher launch angles produce greater maximum height but shorter flight time.', 'True', 'False', NULL, NULL, 'False', 'The statement is False.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'At the very top of its path, the projectile''s vertical velocity is momentarily zero.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'If thrown horizontally and dropped from the same height, both hit the ground at the same time.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Horizontal velocity stays constant if air resistance is ignored.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Gravity acts both horizontally and vertically on a moving projectile.', 'True', 'False', NULL, NULL, 'False', 'The statement is False.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Greater launch speed increases both range and maximum height.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Range depends on the square of the initial speed.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Air resistance makes the actual range shorter than the ideal calculation.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Maximum height depends mostly on the vertical component of velocity.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Projectile motion applies to sports like basketball, sepak takraw, and archery.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Launch angle has no effect on how long the projectile stays in the air.', 'True', 'False', NULL, NULL, 'False', 'The statement is False.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'A ball thrown straight up has zero horizontal velocity throughout its flight.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Symmetry means speed is equal at equal heights above launch level.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Projectile motion only happens when objects move straight up or down.', 'True', 'False', NULL, NULL, 'False', 'The statement is False.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Even without air resistance, total speed is lowest at the highest point.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Increasing launch speed four times doubles the range.', 'True', 'False', NULL, NULL, 'False', 'The statement is False.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Long jumpers aim for fast runup plus an angle close to 45°.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'The horizontal and vertical motions affect each other strongly.', 'True', 'False', NULL, NULL, 'False', 'The statement is False.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'At landing level equal to launch, speed matches speed at launch.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Steeper angle means more time in air but less horizontal distance covered.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Earth''s curvature is usually ignored in basic Grade 10 projectile calculations.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Only mass determines how far a projectile will travel.', 'True', 'False', NULL, NULL, 'False', 'The statement is False.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'The ideal model assumes no air resistance and constant gravity.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Angle and speed together determine the path of the projectile.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000301', 2, 'post_test', 'Projectile motion follows a parabolic shape under ideal conditions.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Momentum equals mass multiplied by velocity (p = m×v).', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'A heavy slow object can have the same momentum as a light fast object.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'In an isolated system, total momentum before collision equals total momentum after.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Elastic collisions conserve both momentum and kinetic energy.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Inelastic collisions conserve momentum but lose some kinetic energy.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Perfectly inelastic means objects stick together after impact.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Force multiplied by time equals change in momentum (impulsemomentum theorem).', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Increasing stopping time reduces the average force experienced.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Seatbelts and airbags work mainly by lengthening the stopping time.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'A fast small object can have more momentum than a slow large one.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Momentum depends on mass and speed only, not direction.', 'True', 'False', NULL, NULL, 'False', 'The statement is False.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'When a cannon fires, recoil shows momentum conservation.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Billiard ball collisions are nearly perfectly elastic.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Clay sticking to a wall is an example of perfectly elastic collision.', 'True', 'False', NULL, NULL, 'False', 'The statement is False.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'A jeepney has more momentum than a motorcycle at the same speed.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'If velocity doubles, momentum also doubles.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Total momentum is always conserved even if kinetic energy is not.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Crumple zones in cars extend collision time to lower impact force.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Catching an egg while pulling your hand back reduces force by increasing time.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Momentum is a scalar quantity with no direction.', 'True', 'False', NULL, NULL, 'False', 'The statement is False.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Stationary objects have zero momentum.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Any change in momentum requires an applied force over time.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Two cars with equal speed and mass colliding headon each experience similar force as hitting a wall.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Mass alone determines how hard it is to stop a moving object.', 'True', 'False', NULL, NULL, 'False', 'The statement is False.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Doubling both mass and velocity quadruples the momentum.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'In single displacement collisions, one object loses momentum the other gains it.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Restitution is perfect in ideal elastic collisions.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Heavy trucks need longer stopping distances even at same speed as cars.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'Momentum conservation applies to all collision types.', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true),
('b0000000-0000-0000-0000-000000000302', 2, 'post_test', 'The unit for momentum is kilogrammeter per second (kg·m/s).', 'True', 'False', NULL, NULL, 'True', 'The statement is True.', true);
